import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import { Checkbox } from './Checkbox';

describe('Checkbox', () => {
  test('should render without crash', () => {
    render(<Checkbox label="Label test" />);
    expect(screen.getByText('Label test')).toBeInTheDocument();
  });

  test('should render without crash when checked', () => {
    render(<Checkbox label="Label test" checked />);
    expect(screen.getByText('Label test')).toBeInTheDocument();
  });

  test('should render without crash with error message', () => {
    render(<Checkbox label="Label test" error="Error Message" />);

    expect(screen.getByText('Label test')).toBeInTheDocument();
    expect(screen.getByText('Error Message')).toBeInTheDocument();
  });

  test('should render with checked as indeterminate', () => {
    render(<Checkbox label="Label test" checked="indeterminate" />);

    expect(screen.getByText('Label test')).toBeInTheDocument();
    expect(document.querySelector('button').getAttribute('data-state')).toBe('indeterminate');
  });

  test('should render without crash disabled and not to be clickable', () => {
    const mockFunction = jest.fn();

    render(<Checkbox label="Label test" disabled onClick={mockFunction} />);

    fireEvent.click(screen.getByText('Label test'));

    expect(mockFunction).not.toBeCalled();
  });

  test('should render check icon when click', () => {
    const handleClickMock = jest.fn();
    render(<Checkbox label="Label test" onClick={handleClickMock} />);

    const button = document.querySelector('button');
    fireEvent.click(button);

    expect(button.getAttribute('data-state')).toBe('checked');
    expect(handleClickMock).toHaveBeenCalled();
  });

  test('should remove check icon when click', () => {
    const handleClickMock = jest.fn();
    render(<Checkbox label="Label test" onClick={handleClickMock} />);

    const button = document.querySelector('button');
    fireEvent.click(button);
    expect(button.getAttribute('data-state')).toBe('checked');

    fireEvent.click(button);
    expect(button.getAttribute('data-state')).toBe('unchecked');

    expect(handleClickMock).toHaveBeenCalledTimes(2);
  });

  test('should render without crash', () => {
    render(<Checkbox label="Label test" />);
    expect(screen.getByText('Label test')).toBeInTheDocument();
  });
});
